package middleware

import (
	"net/http"
	"net/http/httptest"
	"testing"
)

func TestCORS(t *testing.T) {
	allowedOrigins := []string{"https://app.example.com", "https://admin.example.com"}
	mw := CORS(allowedOrigins)

	handler := mw(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusOK)
	}))

	tests := []struct {
		name           string
		method         string
		origin         string
		expectedStatus int
		expectedHeader string
	}{
		{
			name:           "Allowed Origin",
			method:         "GET",
			origin:         "https://app.example.com",
			expectedStatus: http.StatusOK,
			expectedHeader: "https://app.example.com",
		},
		{
			name:           "Disallowed Origin",
			method:         "GET",
			origin:         "https://malicious.com",
			expectedStatus: http.StatusOK,
			expectedHeader: "",
		},
		{
			name:           "Preflight Allowed",
			method:         "OPTIONS",
			origin:         "https://admin.example.com",
			expectedStatus: http.StatusNoContent,
			expectedHeader: "https://admin.example.com",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			req := httptest.NewRequest(tt.method, "/", nil)
			if tt.origin != "" {
				req.Header.Set("Origin", tt.origin)
			}
			rec := httptest.NewRecorder()

			handler.ServeHTTP(rec, req)

			if rec.Code != tt.expectedStatus {
				t.Errorf("expected status %d, got %d", tt.expectedStatus, rec.Code)
			}

			gotHeader := rec.Header().Get("Access-Control-Allow-Origin")
			if gotHeader != tt.expectedHeader {
				t.Errorf("expected header %q, got %q", tt.expectedHeader, gotHeader)
			}
		})
	}
}
```

### Step 2: Implement CORS Middleware
Now I will implement the logic in `internal/middleware/cors.go`.

```go
package middleware

import (
	"net/http"
)

// CORS returns a middleware that handles Cross-Origin Resource Sharing.
func CORS(allowedOrigins []string) func(http.Handler) http.Handler {
	originsMap := make(map[string]bool)
	for _, o := range allowedOrigins {
		originsMap[o] = true
	}

	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			origin := r.Header.Get("Origin")

			// Only set headers if the origin is explicitly allowed
			if originsMap[origin] {
				w.Header().Set("Access-Control-Allow-Origin", origin)
				w.Header().Set("Access-Control-Allow-Methods", "GET, POST, PUT, DELETE, OPTIONS")
				w.Header().Set("Access-Control-Allow-Headers", "Content-Type, Authorization")
				w.Header().Set("Access-Control-Allow-Credentials", "true")
			}

			// Handle preflight requests
			if r.Method == http.MethodOptions {
				if originsMap[origin] {
					w.WriteHeader(http.StatusNoContent)
					return
				}
				// If OPTIONS but not allowed origin, we can either let it fall through 
				// or block it. Standard practice is to return 204 only for allowed.
			}

			next.ServeHTTP(w, r)
		})
	}
}
```

