package middleware

import (
	"net/http"
	"strings"
)

func AuthV2Middleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		// 1. Immediate rejection of legacy X-API-Key
		if r.Header.Get("X-API-Key") != "" {
			http.Error(w, "Legacy X-API-Key is no longer supported. Use OAuth2 Bearer tokens.", http.StatusUnauthorized)
			return
		}

		// 2. Enforce Bearer Token
		authHeader := r.Header.Get("Authorization")
		if authHeader == "" || !strings.HasPrefix(authHeader, "Bearer ") {
			http.Error(w, "Missing or invalid Authorization header.", http.StatusUnauthorized)
			return
		}

		// 3. Proceed to Token Validation (Logic omitted for brevity)
		// token := strings.TrimPrefix(authHeader, "Bearer ")
		// if !isValid(token) { ... }

		next.ServeHTTP(w, r)
	})
}
```

