type RateLimitInfo struct {
	Limit     int
	Remaining int
	Reset     time.Time
}

// MemoryRateLimiter is a simple in-memory implementation of RateLimiter
type MemoryRateLimiter struct {
	mu      sync.Mutex
	limits  map[string]*bucket
	rate    int
	burst   int
	expires time.Duration
}

type bucket struct {
	tokens    int
	lastCheck time.Time
}

func NewMemoryRateLimiter(rate int, burst int) *MemoryRateLimiter {
	return &MemoryRateLimiter{
		limits:  make(map[string]*bucket),
		rate:    rate,
		burst:   burst,
		expires: time.Hour,
	}
}

func (l *MemoryRateLimiter) Allow(key string) (bool, RateLimitInfo) {
	l.mu.Lock()
	defer l.mu.Unlock()

	now := time.Now()
	b, ok := l.limits[key]
	if !ok {
		b = &bucket{tokens: l.burst, lastCheck: now}
		l.limits[key] = b
	}

	// Simple token bucket logic
	elapsed := now.Sub(b.lastCheck)
	newTokens := int(elapsed.Seconds() * float64(l.rate))
	if newTokens > 0 {
		b.tokens += newTokens
		if b.tokens > l.burst {
			b.tokens = l.burst
		}
		b.lastCheck = now
	}

	allowed := false
	if b.tokens > 0 {
		b.tokens--
		allowed = true
	}

	return allowed, RateLimitInfo{
		Limit:     l.burst,
		Remaining: b.tokens,
		Reset:     now.Add(time.Second), // Simplified reset time
	}
}

// RateLimit returns a middleware that performs rate limiting
